function checkpoint(snapshot,label){undoStack.push({snapshot:snapshot||eco.snapshot(),label});if(undoStack.length>15)undoStack.shift();$('#undo').disabled=false;}
function undo(){if(!undoStack.length)return;const item=undoStack.pop();eco.restore(item.snapshot);drawn.clear();selection=null;$('#selection-card').hidden=true;$('#undo').disabled=!undoStack.length;terrainRevision=-1;applyTheme();if(tool==='walk'&&!eco.player?.enabled)selectTab('observe');updateUI();toast(`Undid ${item.label}. World rewound to that moment.`);}
function resize(){const r=canvas.getBoundingClientRect();cssW=r.width;cssH=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(cssW*dpr);canvas.height=Math.round(cssH*dpr);ctx.imageSmoothingEnabled=false;if(firstSize&&cssW>0){cam.p=cssW<600?20:Math.max(14,Math.min(cssW/W,cssH/H));firstSize=false;}boundCamera();}
new ResizeObserver(resize).observe($('#world-view'));
function boundCamera(){const hw=cssW/cam.p/2,hh=cssH/cam.p/2;cam.x=hw>=W/2?W/2:Math.max(hw-1,Math.min(W-hw+1,cam.x));cam.y=hh>=H/2?H/2:Math.max(hh-1,Math.min(H-hh+1,cam.y));}
function zoom(mult,px=cssW/2,py=cssH/2){const wx=cam.x+(px-cssW/2)/cam.p,wy=cam.y+(py-cssH/2)/cam.p;cam.p=Math.max(Math.min(cssW/W,cssH/H)*.85,Math.min(48,cam.p*mult));cam.x=wx-(px-cssW/2)/cam.p;cam.y=wy-(py-cssH/2)/cam.p;boundCamera();}
