function terrainCache(){
 const seed=hash(eco.seed);g.clearRect(0,0,terrain.width,terrain.height);
 for(const c of eco.cells){const x=c.x*16,y=c.y*16,v=c.variant;
  if(c.terrain==='water'){g.fillStyle=waterColor(eco);g.fillRect(x,y,16,16);g.fillStyle='#4e9299';if(v%2===0)g.fillRect(x+3,y+8,5,1);continue;}
  const dry=c.food<.25;g.fillStyle=groundColor(c,eco);g.fillRect(x,y,16,16);
  for(let k=0;k<5;k++){let xx=(v*5+k*11+c.x*3)%15,yy=(v*7+k*5+c.y*2)%15;g.fillStyle=k%2?'#aac27025':'#203b2d21';g.fillRect(x+xx,y+yy,k%2?2:1,1);}
  if(c.food>.45&&v%2===0){g.fillStyle='#bdd27540';g.fillRect(x+5,y+9,1,3);g.fillRect(x+6,y+10,1,2);g.fillStyle='#3455313b';g.fillRect(x+12,y+4,1,2);}
  if(c.terrain==='land'){for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){if(eco.cell(c.x+dx,c.y+dy)?.terrain!=='water')continue;g.fillStyle=shoreColor(eco);if(dx)g.fillRect(x+(dx>0?13:0),y,3,16);else g.fillRect(x,y+(dy>0?13:0),16,3);g.fillStyle='#627955';if(dx)g.fillRect(x+(dx>0?12:3),y,1,16);else g.fillRect(x,y+(dy>0?12:3),16,1);}}
 }
 for(const c of eco.cells.filter(c=>c.terrain==='water')){const x=c.x*16,y=c.y*16;for(const[dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]])if(eco.cell(c.x+dx,c.y+dy)?.terrain==='land'){g.fillStyle='#89b7aa';if(dx)g.fillRect(x+(dx>0?15:0),y,1,16);else g.fillRect(x,y+(dy>0?15:0),16,1);}}
 terrainRevision=eco.revision;
}
function draw(t){
 if(!cssW||!cssH)return;if(tool==='walk'&&eco.player?.enabled&&eco.tweaks.follow&&!gesture){cam.x+=(eco.player.x+.5-cam.x)*.12;cam.y+=(eco.player.y+.5-cam.y)*.12;boundCamera();}if(terrainRevision!==eco.revision)terrainCache();const p=cam.p,ox=cssW/2-cam.x*p,oy=cssH/2-cam.y*p;
 ctx.setTransform(dpr,0,0,dpr,0,0);if(!reduced&&eco.tweaks.shake&&eco.shake>0)ctx.translate(Math.sin(t*51)*eco.shake,Math.cos(t*47)*eco.shake*.6);ctx.imageSmoothingEnabled=false;ctx.fillStyle='#243f35';ctx.fillRect(0,0,cssW,cssH);ctx.fillStyle='#47694c44';for(let y=8;y<cssH;y+=24)for(let x=8;x<cssW;x+=24)ctx.fillRect(x,y,1,1);
 ctx.drawImage(terrain,Math.round(ox),Math.round(oy),W*p,H*p);
 let xmin=Math.max(0,Math.floor(-ox/p)-1),xmax=Math.min(W-1,Math.ceil((cssW-ox)/p)),ymin=Math.max(0,Math.floor(-oy/p)-1),ymax=Math.min(H-1,Math.ceil((cssH-oy)/p));
 const pixel=p/16;drawDetails(ctx,eco,{p,ox,oy,cssW,cssH},t,reduced,'ground');
 if(!reduced){ctx.fillStyle='#add0bd60';for(let y=ymin;y<=ymax;y++)for(let x=xmin;x<=xmax;x++){let c=eco.cell(x,y);if(c.terrain==='water'&&(x*7+y*3)%9===0){const wave=Math.floor(t*.7+c.variant)%4;ctx.fillRect(ox+x*p+(3+wave)*pixel,oy+y*p+(5+c.variant)*pixel,(3+wave%2)*pixel,pixel);}}}
 for(const a of eco.entities){let pos=drawn.get(a.id);if(!pos){pos={x:a.x,y:a.y};drawn.set(a.id,pos);}if(reduced){pos.x=a.x;pos.y=a.y;}else{pos.x+=(a.x-pos.x)*.18;pos.y+=(a.y-pos.y)*.18;}}
 if(drawn.size>eco.entities.length+50){const living=new Set(eco.entities.map(a=>a.id));for(const id of drawn.keys())if(!living.has(id))drawn.delete(id);}
 for(let y=ymin;y<=ymax;y++){
  for(let x=xmin;x<=xmax;x++){const c=eco.cell(x,y);let name=c.terrain==='rock'?'rock':c.plant;if(!name)continue;let sx=ox+x*p,sy=oy+y*p;const grow=name==='rock'?1:Math.max(.4,c.growth);const size=p*(name==='tree'?1.25:name==='flower'?.85:1)*grow;const dx=sx+(p-size)/2,dy=sy+p-size;
   softShadow(ctx,sx,sy,pixel,name==='tree'?1:.7,eco.tweaks.shadow);
   if(name==='tree'&&!reduced){const sway=Math.sin(t*1.2+x*.8+y*.4)>.75?pixel:0;sprite(ctx,name,Math.round(dx+sway),Math.round(dy),size);}
   else{sprite(ctx,name,Math.round(dx),Math.round(dy),size);if(name==='flower'&&c.variant%3===0){ctx.fillStyle='#f6df9b';ctx.fillRect(dx+size*.4,dy+size*.35,2*pixel,2*pixel);}}
  }
  for(const a of eco.entities){const pos=drawn.get(a.id);
   if(Math.floor(pos.y)!==y||pos.x<xmin-1||pos.x>xmax+1)continue;let sx=ox+pos.x*p,sy=oy+pos.y*p;const moving=Math.abs(pos.x-a.x)+Math.abs(pos.y-a.y)>.1;const hop=!reduced&&moving&&a.type==='rabbit'?Math.abs(Math.sin(t*12+a.id))*1.5*pixel:0;const fly=(a.type==='bee'||SPECIES[a.type]?.habitat==='air')?(reduced?2:3+Math.sin(t*4+a.flight))*pixel:0;const size=p*(a.age<15?.78:1);softShadow(ctx,sx,sy,pixel,.6,eco.tweaks.shadow);sprite(ctx,a.type,Math.round(sx+(p-size)/2),Math.round(sy-hop-fly),size,reduced?0:Math.floor(t*(a.type==='bee'?10:4))%2,a.facing<0);
   if(selection?.id===a.id){ctx.strokeStyle='#f4ecc1';ctx.lineWidth=1.5;ctx.strokeRect(sx+pixel,sy+2*pixel,p-2*pixel,p-2*pixel);}
  }
 }
 if(grid){ctx.strokeStyle='#142b243d';ctx.lineWidth=1;ctx.beginPath();for(let x=xmin;x<=xmax+1;x++){ctx.moveTo(ox+x*p,Math.max(0,oy));ctx.lineTo(ox+x*p,Math.min(cssH,oy+H*p));}for(let y=ymin;y<=ymax+1;y++){ctx.moveTo(Math.max(0,ox),oy+y*p);ctx.lineTo(Math.min(cssW,ox+W*p),oy+y*p);}ctx.stroke();}
 if(selection?.cell||keyboardCursor){const c=keyboardCursor||selection.cell;ctx.strokeStyle='#f1ecc7';ctx.lineWidth=2;ctx.strokeRect(ox+c.x*p,oy+c.y*p,p,p);}
 if(!reduced&&eco.tweaks.particles>0){for(const e of eco.effects){const sx=ox+(e.x+.5)*p,sy=oy+(e.y+.3)*p-e.ttl*8;ctx.globalAlpha=Math.min(1,e.ttl);ctx.fillStyle=e.type==='heart'?'#ffc2bd':'#f5dd8d';if(e.type==='heart'){ctx.fillRect(sx-3,sy,2,2);ctx.fillRect(sx+1,sy,2,2);ctx.fillRect(sx-2,sy+2,4,2);ctx.fillRect(sx-1,sy+4,2,1);}else{ctx.fillRect(sx-4,sy,2,2);ctx.fillRect(sx+3,sy-3,2,2);}}ctx.globalAlpha=1;}
 const night=(Math.sin(eco.time/DAY*Math.PI*2-Math.PI/2)+1)/2;
 if(night>.6){ctx.fillStyle=`rgba(17,33,53,${(night-.6)*.32})`;ctx.fillRect(0,0,cssW,cssH);}
 if(['rain','storm'].includes(eco.currentWeather())){ctx.fillStyle='#21405420';ctx.fillRect(0,0,cssW,cssH);if(!reduced){ctx.strokeStyle='#d0e9dd66';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<65;i++){let x=(i*97.7+t*20)%cssW,y=(i*63.3+t*230)%cssH;ctx.moveTo(x,y);ctx.lineTo(x-2,y+7);}ctx.stroke();}}
 drawDetails(ctx,eco,{p,ox,oy,cssW,cssH},t,reduced,'front');drawJuice(ctx,{p,ox,oy},t);
 if(stroke?.last&&tool!=='observe'){const{x,y}=stroke.last;ctx.strokeStyle='#eff7c6';ctx.lineWidth=1.5;ctx.strokeRect(ox+(x-brush+1)*p,oy+(y-brush+1)*p,(brush*2-1)*p,(brush*2-1)*p);}
}
const lifeTools=[['tree','Tree','Trees spread slowly and shade the ground.'],['flower','Flowers','Flowers feed bees. Pollination helps them spread.'],['shrub','Berries','Berry bushes provide food for rabbits.'],['rabbit','Rabbit','Rabbits graze, flee foxes, and reproduce.'],['fox','Fox','Foxes hunt rabbits. Too many can deplete their prey.'],['bee','Bee','Bees visit flowers and help them spread.']];
const landTools=[['grass','Grass','Paint fresh grass. Rabbits can graze here.'],['water','Water','Water keeps nearby soil moist. Animals need dry land.'],['erase','Remove','Remove plants or animals. Undo is always available.']];
function renderTools(){if(tool==='walk'){renderPlayerTools();return;}const tools=tab==='land'?landTools:lifeTools;$('#tool-grid').innerHTML=tools.map(([id,label])=>`<button class="tool ${tool===id?'selected':''}" data-tool="${id}" aria-pressed="${tool===id}" title="${label}">${id==='erase'?`<i>${icon('erase')}</i>`:`<canvas data-sprite="${id}" width="16" height="16"></canvas>`}<span>${label}</span></button>`).join('');$('#tool-grid').setAttribute('aria-label',tab==='land'?'Landscape tools':'Add plants and animals');decorate($('#tool-grid'));$$('[data-tool]').forEach(b=>b.onclick=()=>selectTool(b.dataset.tool));$('#tool-grid').style.gridTemplateColumns=tab==='land'?'repeat(3,1fr)':'';}
function selectTab(value){if(eco.player)eco.player.path=[];tab=value;tool='observe';$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',b.dataset.tab===tab);});renderTools();if(value==='land')selectTool('grass');else if(value==='life')selectTool('flower');else updateTool();}
function selectTool(value){if(eco.player)eco.player.path=[];tool=value;if(tab==='observe'){tab='life';$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',b.dataset.tab===tab);});}$$('[data-tool]').forEach(b=>{b.classList.toggle('selected',b.dataset.tool===tool);b.setAttribute('aria-pressed',b.dataset.tool===tool);});selection=null;$('#selection-card').hidden=true;updateTool();}
function updateTool(){if(tool==='walk'){$('#tool-description').textContent='Tap a destination. Gather nearby; face water to build a bridge.';$('#brush-control').hidden=true;$('#gesture-hint').textContent='Tap to walk · Drag to explore';canvas.classList.remove('paint');return;}const info=[...lifeTools,...landTools].find(t=>t[0]===tool)||(SPECIES[tool]?[tool,SPECIES[tool].name,SPECIES[tool].description||SPECIES[tool].role]:tool==='mushroom'?['mushroom','Mushrooms','Feed beetles, slimes, and fireflies.']:tool==='crystal'?['crystal','Crystals','Wisps carry their resonance into luminous flowers.']:null);$('#tool-description').textContent=info?info[2]:'Choose Life or Land to shape this world.';$('#brush-control').hidden=tool==='observe'||!!SPECIES[tool];$('#gesture-hint').innerHTML=icon(tool==='observe'?'hand':'sprout')+(tool==='observe'?'Drag to explore · Tap to inspect':SPECIES[tool]?'Tap to add · Two fingers to move':'Drag to paint · Two fingers to move');canvas.classList.toggle('paint',tool!=='observe');announce(tool==='observe'?'Observe mode. Drag to explore, tap to inspect.':`${info[1]} selected. ${info[2]}`);}
function updateUI(){const c=eco.counts();$('#day').textContent=`Day ${String(eco.day()).padStart(2,'0')}`;$('#note-day').textContent=`DAY ${String(eco.day()).padStart(2,'0')}`;const rain=['rain','storm'].includes(eco.currentWeather());$('#season').textContent=`${eco.season()} · ${WEATHERS[eco.currentWeather()]||'Clear'}`;$('#weather-icon').innerHTML=icon(rain?'rain':'sun');$('#world-status').textContent=paused?'WORLD PAUSED':tool==='walk'?'THE WANDERER':(ENVIRONMENTS[eco.environment]?.name||'Woodland').toUpperCase();$('.live-dot').style.background=paused?'#e4b575':'';$('#seed-label').textContent=eco.seed;for(const type of ['rabbit','fox','bee'])$(`#count-${type}`).textContent=c[type];$('#open-stats').setAttribute('aria-label',`Populations: ${c.rabbit} rabbits, ${c.fox} foxes, ${c.bee} bees. Open ecosystem trends.`);$('#rain .rain-duration').textContent=eco.rainBoost>0?`${Math.ceil(eco.rainBoost)}s`:'24s';$('#rain').disabled=eco.rainBoost>0;
 const notesKey=eco.events.slice(0,3).map(e=>e.text).join('');if(lastEvents!==notesKey){lastEvents=notesKey;$('#notes').innerHTML=eco.events.slice(0,3).map(e=>`<div class="note"><i>${icon(e.type in paths?e.type:'leaf')}</i><span>${e.text}</span></div>`).join('');$('#footer-status').textContent=eco.events[0]?.text||'';}
 if(selection)updateInspector();if(dialogType==='stats'&&$('#dialog').open)refreshStats();updateAdventureUI();}
function setPaused(value){paused=value;$('#pause').innerHTML=icon(paused?'play':'pause');$('#pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation');$('#pause').title=paused?'Resume (Space)':'Pause (Space)';updateUI();announce(paused?'World paused. You can still make changes.':'World resumed.');}
function inspect(x,y){const near=eco.entities.map(a=>({a,d:Math.hypot(a.x+.5-x,a.y+.5-y)})).filter(v=>v.d<1.25).sort((a,b)=>a.d-b.d)[0];selection=near?{id:near.a.id}:{cell:{x:Math.floor(x),y:Math.floor(y)}};if(!near&&!eco.cell(x,y)){selection=null;$('#selection-card').hidden=true;return;}updateInspector();}
function updateInspector(){const card=$('#selection-card');let name,state,sp,amount,label,caption;
 if(selection.id){const a=eco.entities.find(a=>a.id===selection.id);if(!a){card.innerHTML=`<div class="selection-heading"><div><h3>Life moves on.</h3><p>This creature has died.</p></div><button id="dismiss-inspector" aria-label="Close inspector">${icon('close')}</button></div><p class="selection-caption">Its nutrients return to the soil.</p>`;$('#dismiss-inspector').onclick=()=>{selection=null;card.hidden=true;};return;}name=SPECIES[a.type].name;state=a.state;sp=a.type;amount=Math.round(a.energy);label='Energy';caption=`${SPECIES[a.type].role} · ${Math.floor(a.age/DAY)} days old<br>Eats ${SPECIES[a.type].diet.toLowerCase()}.`;
 }else{const c=eco.cell(selection.cell.x,selection.cell.y);if(!c)return;name=c.plant?({tree:'Woodland tree',flower:c.luminous?'Starflowers':'Wildflowers',shrub:'Berry bush',mushroom:'Mushrooms',crystal:'Resonant crystal'}[c.plant]):c.terrain==='water'?'Fresh water':c.terrain==='rock'?'Rock':'Meadow';state=c.pollen>0?'Recently pollinated':c.terrain==='water'?'Moistens nearby soil':c.plant?(c.growth>.8?'Mature':'Growing'):'Open habitat';sp=c.plant||c.terrain;sp=sp==='land'?'grass':sp;amount=Math.round(c.moisture*100);label='Soil moisture';caption=c.structure?`A ${c.structure}. Built by the wanderer.`:c.fire>0?'Burning. Rain can extinguish this fire.':c.plant==='mushroom'?'Feeds decomposers, slimes, and fireflies.':c.plant==='crystal'?'Sustains wisps. Aurora recharges its resonance.':c.terrain==='water'?'Plants within 3 tiles benefit from this water.':c.plant==='tree'?'Seeds spread nearby. Shade slows grass growth.':c.plant==='flower'?'Feeds bees. Pollinated flowers spread faster.':c.plant==='shrub'?'Berries replenish and feed hungry rabbits.':`Grass food ${Math.round(c.food*100)}% · Fertility ${Math.round(c.fertility*100)}%`;}
 card.hidden=false;card.innerHTML=`<div class="selection-heading"><canvas data-sprite="${sp}" width="16" height="16"></canvas><div><h3>${name}</h3><p>${state}</p></div><button id="dismiss-inspector" aria-label="Close inspector">${icon('close')}</button></div><div class="selection-data"><span>${label}</span><span>${amount}%</span></div><div class="meter"><div style="width:${amount}%"></div></div><p class="selection-caption">${caption}</p>`;decorate(card);$('#dismiss-inspector').onclick=()=>{selection=null;card.hidden=true;};}
function point(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
function worldPoint(p){return{x:cam.x+(p.x-cssW/2)/cam.p,y:cam.y+(p.y-cssH/2)/cam.p};}
function applyPaint(p){const w=worldPoint(p),x=Math.floor(w.x),y=Math.floor(w.y);if(!stroke||stroke.visited.has(`${x},${y}`))return;stroke.visited.add(`${x},${y}`);stroke.last={x,y};const result=eco.paint(tool,x,y,brush);if(result.ok){stroke.changed=true;terrainRevision=-1;}else if(result.message!==lastPaintError){lastPaintError=result.message;toast(result.message);}}
function endStroke(){if(stroke?.changed){if(tool==='water'||tool==='grass')eco.refreshWater();checkpoint(stroke.snapshot,tool==='erase'?'removal':`${tool} placement`);updateUI();}stroke=null;lastPaintError='';}
canvas.addEventListener('pointerdown',e=>{if(e.button&&e.pointerType==='mouse')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=point(e);pointers.set(e.pointerId,p);keyboardCursor=null;
 if(pointers.size===2){if(stroke){if(stroke.changed){eco.restore(stroke.snapshot);terrainRevision=-1;}stroke=null;}const[a,b]=[...pointers.values()];gesture={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),mid:{x:(a.x+b.x)/2,y:(a.y+b.y)/2}};return;}
 if(pointers.size>2)return;gesture={type:['observe','walk'].includes(tool)?'pan':'paint',start:p,last:p,moved:false};if(!['observe','walk'].includes(tool)){stroke={snapshot:eco.snapshot(),visited:new Set(),changed:false};if(e.pointerType==='mouse')applyPaint(p);}
});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const p=point(e);pointers.set(e.pointerId,p);if(pointers.size>=2){const[a,b]=[...pointers.values()];const mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},distance=Math.hypot(a.x-b.x,a.y-b.y);if(gesture?.type==='pinch'){zoom(distance/Math.max(1,gesture.distance),mid.x,mid.y);cam.x-=(mid.x-gesture.mid.x)/cam.p;cam.y-=(mid.y-gesture.mid.y)/cam.p;boundCamera();}gesture={type:'pinch',distance,mid};return;}
 if(!gesture||gesture.type==='pinch')return;const moved=Math.hypot(p.x-gesture.start.x,p.y-gesture.start.y)>4;if(moved)gesture.moved=true;
 if(gesture.type==='pan'){if(tool==='walk'&&gesture.moved)eco.tweaks.follow=false;cam.x-=(p.x-gesture.last.x)/cam.p;cam.y-=(p.y-gesture.last.y)/cam.p;boundCamera();}else if(!SPECIES[tool]){if(gesture.moved){const prev=gesture.last,steps=Math.max(1,Math.ceil(Math.hypot(p.x-prev.x,p.y-prev.y)/(cam.p*.5)));for(let i=0;i<=steps;i++)applyPaint({x:prev.x+(p.x-prev.x)*i/steps,y:prev.y+(p.y-prev.y)*i/steps});}}gesture.last=p;
});
function pointerEnd(e){if(!pointers.has(e.pointerId))return;const p=point(e);if(e.type!=='pointercancel'&&pointers.size===1&&gesture&&gesture.type!=='pinch'){if(gesture.type==='pan'&&!gesture.moved){const w=worldPoint(p);if(tool==='walk'){const result=eco.pathTo(Math.floor(w.x),Math.floor(w.y));if(!result.ok)toast(result.message);else feedbackAt(Math.floor(w.x),Math.floor(w.y),'step');}else inspect(w.x,w.y);}else if(gesture.type==='paint'&&(!gesture.moved||!SPECIES[tool]))applyPaint(p);}pointers.delete(e.pointerId);if(!pointers.size){endStroke();gesture=null;}}
canvas.addEventListener('pointerup',pointerEnd);canvas.addEventListener('pointercancel',pointerEnd);canvas.addEventListener('wheel',e=>{e.preventDefault();const p=point(e);zoom(e.deltaY<0?1.12:1/1.12,p.x,p.y);},{passive:false});
canvas.addEventListener('keydown',e=>{if(tool==='walk')return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(!keyboardCursor)keyboardCursor={x:Math.floor(cam.x),y:Math.floor(cam.y)};keyboardCursor.x=Math.max(0,Math.min(W-1,keyboardCursor.x+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0)));keyboardCursor.y=Math.max(0,Math.min(H-1,keyboardCursor.y+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)));const c=keyboardCursor;cam.x=c.x;cam.y=c.y;boundCamera();announce(`Tile ${c.x+1}, ${c.y+1}: ${eco.cell(c.x,c.y).plant||eco.cell(c.x,c.y).terrain}`);}if(e.key==='Enter'){e.preventDefault();const c=keyboardCursor||{x:Math.floor(cam.x),y:Math.floor(cam.y)};if(tool==='observe')inspect(c.x+.5,c.y+.5);else{const old=eco.snapshot(),r=eco.paint(tool,c.x,c.y,brush);if(r.ok){checkpoint(old,`${tool} placement`);eco.refreshWater();terrainRevision=-1;updateUI();announce(`${tool} placed.`);}else toast(r.message);}}});
function openDialog(type,title,body){endStroke();dialogType=type;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').classList.toggle('dev-dialog',type==='dev');if(!$('#dialog').open)$('#dialog').showModal();decorate($('#dialog'));}
function closeDialog(){$('#dialog').close();$('#dialog').classList.remove('dev-dialog');dialogType='';acc=0;}
function guide(){openDialog('help','A world of small connections.',`<p class="dialog-intro">There’s no score and no perfect balance. Make a change, watch the ripples, and follow your curiosity.</p><div class="guide-item"><canvas data-sprite="rabbit" width="16" height="16"></canvas><div><h3>Rabbits graze. Foxes hunt.</h3><p>Well-fed animals reproduce. Rabbits avoid foxes; too many grazers can strip a meadow. Hungry animals eventually die.</p></div></div><div class="guide-item"><canvas data-sprite="bee" width="16" height="16"></canvas><div><h3>Flowers feed a little more life.</h3><p>Bees eat nectar and pollinate flowers, helping them spread. Trees spread too, shading the grass underneath.</p></div></div><div class="guide-item"><canvas data-sprite="water" width="16" height="16"></canvas><div><h3>Everything returns to the soil.</h3><p>Water and rain help plants recover. Dead creatures enrich the soil. Seasons change growth rates every six days.</p></div></div><div class="guide-tip"><b>Try this:</b> plant flowers beside water, add a few bees, then watch at 3×. Or introduce a fox to a rabbit-rich meadow.</div><div class="guide-item"><div><h3>A few things to know</h3><p><b>Observe:</b> drag to explore, tap to inspect.<br><b>Life / Land:</b> choose a tool, then tap or paint.<br><b>Two fingers:</b> pan and pinch in any mode.<br><b>Undo:</b> rewinds to before your last intervention.<br><b>Time:</b> a day is 30 seconds at 1×. Closing the tab ends this world; keep it open to continue.<br><b>Keyboard:</b> Space to pause, + / − to zoom, Ctrl/⌘ Z to undo. Focus the world and use arrow keys + Enter.</p></div></div><label class="motion-setting">Gentle motion <input type="checkbox" id="gentle" ${reduced?'checked':''}></label><p class="attribution">A playful model of ecological relationships, with simplified rules. Interface guided by <a href="https://www.nngroup.com/articles/ten-usability-heuristics/" target="_blank" rel="noopener noreferrer">Jakob Nielsen’s usability heuristics</a>.</p>`);$('#gentle').onchange=e=>{reduced=e.target.checked;};}
function newWorldDialog(){let preset=eco.preset;openDialog('new','A fresh beginning.',`<p class="dialog-intro">Generate a new habitat and see which life takes hold. You can undo this to return to your current world.</p><label class="dialog-field" for="world-seed">World seed</label><input id="world-seed" maxlength="28" autocomplete="off" spellcheck="false" value="FERN-${Math.floor(100+Math.random()*899)}"><label class="dialog-field">Habitat</label><div class="preset-list">${[['woodland','Woodland'],['meadow','Meadow'],['wetland','Wetland']].map(([id,label])=>`<button class="preset ${preset===id?'active':''}" data-preset="${id}" aria-pressed="${preset===id}">${label}</button>`).join('')}</div><p class="attribution">The same seed and habitat create the same starting world.</p><div class="dialog-actions"><button id="cancel-world" class="secondary">Keep this world</button><button id="generate" class="primary">Create world</button></div>`);$$('[data-preset]').forEach(b=>b.onclick=()=>{preset=b.dataset.preset;$$('[data-preset]').forEach(a=>{a.classList.toggle('active',a===b);a.setAttribute('aria-pressed',a===b);});});$('#cancel-world').onclick=closeDialog;$('#generate').onclick=()=>{const input=$('#world-seed'),seed=input.value.trim();if(!seed){input.setAttribute('aria-invalid','true');input.focus();input.placeholder='Enter a word or number';return;}checkpoint(eco.snapshot(),'new world');eco.reset(seed,preset);applyTheme();drawn.clear();selection=null;$('#selection-card').hidden=true;terrainRevision=-1;setPaused(false);selectTab('observe');closeDialog();updateUI();toast('A new world is alive. Undo brings the previous one back.');};}
function stats(){openDialog('stats','The living balance.',`<div class="chart-key"><span style="--color:#ece3c4">Rabbits</span><span style="--color:#e99958">Foxes</span><span style="--color:#f6d86d">Bees</span></div><canvas class="chart" id="population-chart" aria-label="Population trends over time" role="img"></canvas><p class="attribution" id="chart-caption"></p><div class="stat-grid"><div class="stat-box"><strong id="stat-green">0%</strong><span>Grass cover</span></div><div class="stat-box"><strong id="stat-born">0</strong><span>Animals born</span></div><div class="stat-box"><strong id="stat-pollen">0</strong><span>Pollinations</span></div></div><p id="health" class="ecosystem-health"></p><div class="guide-tip" id="plant-counts"></div><p class="attribution">Time pauses while this panel is open. Populations follow local interactions; they aren’t scripted to stay balanced.</p>`);refreshStats();}
function refreshStats(){const c=eco.counts();$('#stat-green').textContent=`${c.coverage}%`;$('#stat-born').textContent=eco.births;$('#stat-pollen').textContent=eco.pollinations;$('#health').textContent=c.rabbit===0?'No rabbits remain. Add a few on open grass to restore the food web.':c.bee===0?'No bees remain. Plant flowers and introduce a few pollinators.':c.coverage<30?'Grazing is outpacing growth. Bring rain, plant grass, or introduce a fox.':c.fox>c.rabbit/3?'Predators are plentiful. Watch the rabbit population or add more prey.':'Life is finding its rhythm. Watch for changes as plants spread and populations grow.';$('#plant-counts').textContent=`${c.tree} trees · ${c.flower} flowers · ${c.shrub} berry bushes · ${c.mushroom||0} fungi · ${eco.entities.length} creatures. Full census in Dev tweaks → Journal.`;$('#chart-caption').textContent=`Day ${Math.floor((eco.history[0]?.time||0)/DAY)+1} to day ${eco.day()} · ${c.rabbit} rabbits, ${c.fox} foxes, ${c.bee} bees now.`;const cv=$('#population-chart'),r=cv.getBoundingClientRect(),w=r.width||420,h=150;cv.width=w*2;cv.height=h*2;const cx=cv.getContext('2d');cx.scale(2,2);const max=Math.max(10,...eco.history.map(d=>Math.max(d.rabbit,d.fox,d.bee)));cx.font='11px monospace';cx.fillStyle='#91a494';for(let i=0;i<4;i++){let y=12+i*40;cx.strokeStyle='#35453f';cx.beginPath();cx.moveTo(28,y);cx.lineTo(w,y);cx.stroke();cx.fillText(Math.round(max*(1-i/3)),0,y+4);}for(const type of ['rabbit','fox','bee']){cx.strokeStyle=SPECIES[type].color;cx.lineWidth=2;cx.beginPath();const data=eco.history.length>1?eco.history:[eco.history[0],eco.counts()];data.forEach((n,i)=>{let x=28+i*(w-30)/Math.max(1,data.length-1),y=132-n[type]/max*120;i?cx.lineTo(x,y):cx.moveTo(x,y);});cx.stroke();}}
$$('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$('#brush').onchange=e=>brush=Number(e.target.value);$('#pause').onclick=()=>setPaused(!paused);$$('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);$$('[data-speed]').forEach(s=>{s.classList.toggle('active',s===b);s.setAttribute('aria-pressed',s===b);});announce(`Simulation speed ${speed} times.`);});$('#undo').onclick=undo;$('#rain').onclick=()=>{checkpoint(null,'rain');eco.rain();updateUI();toast(paused?'Rain is ready. Resume time to water the world.':'Rain is falling. Nearby plants will recover.');};$('#zoom-in').onclick=()=>zoom(1.35);$('#zoom-out').onclick=()=>zoom(1/1.35);$('#fit').onclick=fit;$('#grid').onclick=()=>{grid=!grid;$('#grid').setAttribute('aria-pressed',grid);$('#grid').setAttribute('aria-label',grid?'Hide tile grid':'Show tile grid');};$('#help').onclick=guide;$('#new-world').onclick=newWorldDialog;$('#open-stats').onclick=stats;$('#ecosystem-details').onclick=stats;$('#close-dialog').onclick=closeDialog;$('#dialog').addEventListener('close',()=>{dialogType='';acc=0;});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
document.addEventListener('keydown',e=>{if($('#dialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.code==='Space'&&document.activeElement.tagName!=='BUTTON'){e.preventDefault();setPaused(!paused);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}if(e.key==='+'||e.key==='=')zoom(1.2);if(e.key==='-')zoom(1/1.2);if(e.key==='Escape'){selection=null;$('#selection-card').hidden=true;selectTab('observe');}});
document.addEventListener('visibilitychange',()=>{last=0;acc=0;});
function frame(ms){if(!last)last=ms;const dt=Math.min((ms-last)/1000,.1);last=ms;if(!document.hidden){if(!paused&&!$('#dialog').open&&!stroke){acc+=dt*speed;let n=0;while(acc>=.25&&n<8){eco.step(.25);acc-=.25;n++;}}renderTime+=dt;if(ms-lastUI>500){updateUI();lastUI=ms;}draw(renderTime);}requestAnimationFrame(frame);}
const devMenu=createDevMenu({state:()=>({eco,reduced}),openDialog,closeDialog,decorate,toast,selectTool,mutate,applyTheme,afterWorld,enterPlayer,leavePlayer,focusWorld,setReduced:v=>{reduced=v;},enableSound});
$('#dev-tweaks').onclick=()=>devMenu.open();$('#center-player').onclick=()=>{eco.tweaks.follow=true;if(eco.player)focusWorld(eco.player.x,eco.player.y);};
renderTools();updateTool();updateUI();resize();requestAnimationFrame(frame);
function mutate(label,action){const before=eco.snapshot();try{const result=action()||{ok:true};if(result.ok===false){toast(result.message);return result;}checkpoint(before,label);terrainRevision=-1;updateUI();return result;}catch(error){eco.restore(before);terrainRevision=-1;toast('That change could not be applied. Your world was restored.');return{ok:false,message:error.message};}}
function applyTheme(){initSprites(eco.theme);decorate();terrainRevision=-1;}
function focusWorld(x,y){if(Number.isFinite(x)&&Number.isFinite(y)){cam.x=x+.5;cam.y=y+.5;boundCamera();}}
function afterWorld(){drawn.clear();selection=null;$('#selection-card').hidden=true;juice=[];lastNotice=0;applyTheme();selectTab('observe');setPaused(false);updateUI();}
function enterPlayer(save=true){const result=save?mutate('entering the world',()=>eco.enablePlayer()):eco.enablePlayer();if(!result.ok)return;tool='walk';tab='observe';selection=null;$('#selection-card').hidden=true;$$('[data-tab]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});renderPlayerTools();updateTool();focusWorld(eco.player.x,eco.player.y);setPaused(false);speed=1;$$('[data-speed]').forEach(b=>{b.classList.toggle('active',b.dataset.speed==='1');b.setAttribute('aria-pressed',b.dataset.speed==='1');});updateUI();toast('You are the wanderer. Tap open ground to walk.');}
function leavePlayer(){selectTab('observe');updateUI();}
function renderPlayerTools(){const actions=[['gather','grass','Gather'],['tend','flower','Tend'],['bridge','bridge','Bridge'],['sanctuary','sanctuary','Sanctuary'],['rest','camp','Rest'],['journal','ruin','Journal']];$('#tool-grid').style.gridTemplateColumns='';$('#tool-grid').setAttribute('aria-label','Wanderer actions');$('#tool-grid').innerHTML=actions.map(([id,art,label])=>`<button class="tool player-action" data-player-action="${id}" title="${id==='bridge'?'Build bridge · 2 wood':id==='sanctuary'?'Build sanctuary · 5 wood + 4 seeds':label}"><canvas data-sprite="${art}" width="16" height="16"></canvas><span>${label}</span></button>`).join('');decorate($('#tool-grid'));$$('[data-player-action]').forEach(b=>b.onclick=()=>{if(b.dataset.playerAction==='journal'){devMenu.open('journal');return;}const result=mutate(b.dataset.playerAction,()=>eco.playerAction(b.dataset.playerAction));if(result.ok){feedbackAt(eco.player.x,eco.player.y,b.dataset.playerAction);toast(result.message);}});}
function updateAdventureUI(){const p=eco.player;$('#player-hud').hidden=!p?.enabled;if(p?.enabled){$('#player-readout').textContent=`${Math.round(p.hp)} health · ${p.seeds} seeds · ${p.wood} wood`;$('#player-hud').classList.toggle('low-health',p.hp<30);}if(eco.notice&&eco.notice.id!==lastNotice){lastNotice=eco.notice.id;toast(`${eco.notice.title} · Read the journal in Dev tweaks.`,6500);if(p)feedbackAt(p.x,p.y,'discovery');else playTone('discovery');}}
function feedbackAt(x,y,type='place'){const count=reduced?0:Math.round((type==='discovery'?18:7)*eco.tweaks.particles);for(let i=0;i<count;i++){const angle=i*Math.PI*2/Math.max(1,count);juice.push({x:x+.5,y:y+.5,born:renderTime,dx:Math.cos(angle)*(type==='discovery'?1.2:.5),dy:Math.sin(angle)*.5-.5,color:type==='discovery'?'#f3d89e':type==='tend'?'#c6eaa2':'#e1e8c5',ttl:type==='discovery'?1.4:.65});}juice=juice.slice(-100);if(eco.tweaks.haptics&&typeof navigator!=='undefined'&&navigator.vibrate)navigator.vibrate(type==='discovery'?[15,35,15]:10);playTone(type);}
function drawJuice(context,{p,ox,oy},time){juice=juice.filter(e=>time-e.born<e.ttl);if(reduced||eco.tweaks.particles===0)return;for(const e of juice){const age=time-e.born,progress=age/e.ttl;context.globalAlpha=1-progress;context.fillStyle=e.color;context.fillRect(ox+(e.x+e.dx*age)*p,oy+(e.y+e.dy*age+age*age*.15)*p,2,2);}context.globalAlpha=1;}
function enableSound(){try{const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio){eco.tweaks.sound=false;toast('Sound is unavailable in this browser.');return;}if(!audioContext)audioContext=new Audio();audioContext.resume();playTone('discovery');}catch{eco.tweaks.sound=false;toast('Sound could not start. The world still works silently.');}}
function playTone(type){if(!eco.tweaks.sound||!audioContext)return;try{const now=audioContext.currentTime,frequencies=type==='discovery'?[440,554,659]:type==='tend'?[440,587]:[330];frequencies.forEach((hz,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,now+i*.075);g.gain.linearRampToValueAtTime(.035,now+i*.075+.012);g.gain.exponentialRampToValueAtTime(.001,now+i*.075+.18);o.connect(g);g.connect(audioContext.destination);o.start(now+i*.075);o.stop(now+i*.075+.2);});}catch{}}
document.addEventListener('keydown',e=>{if(tool!=='walk'||$('#dialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const direction={w:[0,-1],a:[-1,0],s:[0,1],d:[1,0],ArrowUp:[0,-1],ArrowLeft:[-1,0],ArrowDown:[0,1],ArrowRight:[1,0]}[e.key];if(!direction)return;e.preventDefault();if(e.repeat&&performance.now()-lastPlayerKey<100)return;lastPlayerKey=performance.now();const result=eco.movePlayer(...direction);if(!result.ok&&!e.repeat)toast(result.message);updateUI();});
