 register({name:'read_ecosystem',title:'Read ecosystem',description:'Read the current day, species populations, plant counts, weather, and latest events.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({day:eco.day(),season:eco.season(),weather:eco.currentWeather(),environment:eco.environment,theme:eco.theme,player:eco.player?{enabled:eco.player.enabled,x:eco.player.x,y:eco.player.y,health:Math.round(eco.player.hp),discoveries:eco.player.discovered}:null,paused,speed,populations:eco.counts(),events:eco.events.slice(0,5)})});
 register({name:'set_ecosystem_time',title:'Control ecosystem time',description:'Pause or resume this world and set its simulation speed.',inputSchema:{type:'object',properties:{paused:{type:'boolean'},speed:{type:'number',enum:[1,3,8]}},required:['paused','speed'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.paused!=='boolean'||![1,3,8].includes(input?.speed))throw new Error('Choose paused true or false and speed 1, 3, or 8.');setPaused(input.paused);$(`[data-speed="${input.speed}"]`).click();return{paused,speed};}});
 register({name:'add_ecosystem_life',title:'Add plants or animals',description:'Add a plant or animal on an open land tile. Coordinates are zero-based: x 0–47, y 0–39. This action can be undone.',inputSchema:{type:'object',properties:{species:{type:'string',enum:['tree','flower','shrub','mushroom','crystal',...Object.keys(SPECIES)]},x:{type:'integer',minimum:0,maximum:47},y:{type:'integer',minimum:0,maximum:39}},required:['species','x','y'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(![...lifeTools.map(v=>v[0]),'mushroom','crystal',...Object.keys(SPECIES)].includes(input?.species)||!Number.isInteger(input.x)||!Number.isInteger(input.y)||!eco.cell(input.x,input.y))throw new Error('Choose a valid species and a tile within the world.');const old=eco.snapshot(),result=eco.paint(input.species,input.x,input.y);if(!result.ok)throw new Error(result.message);checkpoint(old,`${input.species} placement`);terrainRevision=-1;updateUI();toast(`${input.species} added.`);return{added:input.species,x:input.x,y:input.y,populations:eco.counts()};}});
 register({name:'run_ecosystem_scenario',title:'Run an ecosystem experiment',description:'Replace the current world with a named dev scenario. Saves an undo checkpoint and uses the same controls as Dev tweaks.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:SCENARIOS.map(s=>s.id)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!SCENARIOS.some(s=>s.id===input?.scenario))throw new Error('Choose one of the named scenarios.');const result=mutate('scenario',()=>eco.scenario(input.scenario));if(!result.ok)throw new Error(result.message);afterWorld();if(eco.player?.enabled)enterPlayer(false);return{scenario:input.scenario,populations:eco.counts(),environment:eco.environment,theme:eco.theme,playerEnabled:!!eco.player?.enabled};}});
